import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.exists(src_folder):
        return {'success': False, 'message': f"Source folder '{src_folder}' does not exist.", 'failed_files': []}
    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder)
    failed_files = []
    files_to_compress = glob(os.path.join(src_folder, '*'))
    processes = []
    for file_path in files_to_compress:
        filename = os.path.basename(file_path)
        compressed_filename = filename + '.gz'
        dst_file_path = os.path.join(dst_folder, compressed_filename)
        try:
            with open(file_path, 'rb') as f_in:
                with open(dst_file_path, 'wb') as f_out:
                    process = subprocess.Popen(['gzip'], stdin=f_in, stdout=f_out)
                    processes.append((process, filename, dst_file_path))
        except Exception as e:
            failed_files.append(filename)

