import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str) or not script_path or not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found at {script_path}")

    process = subprocess.Popen(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    try:
        p = psutil.Process(process.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0.0}

    cpu_usage = 0.0
    memory_usage = 0

    try:
        initial_rss = p.memory_info().rss
    except psutil.NoSuchProcess:
        initial_rss = 0

    start_time = time.time()
    while p.is_running() and time.time() - start_time < timeout:
        try:
            cpu_usage += p.cpu_percent(interval=0.1)
            current_rss = p.memory_info().rss
            memory_usage += (current_rss - initial_rss) if current_rss > initial_rss else 0
            initial_rss = current_rss 
        except psutil.NoSuchProcess:
            break
        except psutil.ZombieProcess:
            break
        time.sleep(0.1)

    if process.poll() is None:
        process.terminate()
        process.wait(timeout=1)

    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}

